<template><Transition name="ui-back"><UiIconButton v-if="visible" class="ui-back" label="返回顶部" @click="goTop"><Icon name="chevronUp" size="sm"/></UiIconButton></Transition></template>
<script setup lang="ts">import{onBeforeUnmount,onMounted,ref}from'vue';import Icon from'@/components/icons/Icon.vue';import UiIconButton from'./UiIconButton.vue';const props=withDefaults(defineProps<{threshold?:number}>(),{threshold:400});const visible=ref(false);function update(){visible.value=window.scrollY>props.threshold}function goTop(){window.scrollTo({top:0,behavior:'smooth'})}onMounted(()=>{update();window.addEventListener('scroll',update,{passive:true})});onBeforeUnmount(()=>window.removeEventListener('scroll',update));</script>
<style scoped>.ui-back{position:fixed;z-index:30;right:20px;bottom:calc(20px + env(safe-area-inset-bottom));box-shadow:var(--ui-shadow-floating,0 6px 16px rgb(31 35 41/.1))}.ui-back-enter-active,.ui-back-leave-active{transition:opacity var(--ui-motion-fast),transform var(--ui-motion-fast)}.ui-back-enter-from,.ui-back-leave-to{opacity:0;transform:translateY(6px)}</style>
